CREATE OR REPLACE FUNCTION GeneratePriorityIndex()
RETURNS TABLE(ARTregID text, art_title text, priority_score numeric) AS $$
BEGIN
    RETURN QUERY
    SELECT ac.ARTregID, ac.art_title, 
        ROUND((COALESCE(ar.HIST_sign, 0) + COALESCE((ar.rating_profile->>'research_score')::numeric, 0) + COALESCE((ar.rating_profile->>'cultural_score')::numeric, 0)) * (10 - CASE ac.conserve_status WHEN 'Excellent' THEN 1 WHEN 'Good' THEN 3 WHEN 'Fair' THEN 5 WHEN 'Poor' THEN 7 WHEN 'Critical' THEN 10 ELSE 5 END) / 30.0, 2)
    FROM ArtifactsCore ac LEFT JOIN ArtifactRatings ar ON ac.ARTregID = ar.ART_link;
END;
$$ LANGUAGE plpgsql;

